func (w *rotatingFileWriter) Close() error {
    w.mu.Lock()
    defer w.mu.Unlock()

    // ← NEW: stop the background flush goroutine
    if w.stopFlush != nil {
        close(w.stopFlush)
        w.stopFlush = nil
    }

    if w.current == nil {
        return nil
    }
    err := w.current.Close()
    w.current = nil
    return err
